// Project Briefing endpoint — the AI Foundation read-out.
//
// When a Claude session boots cold (Dispatch, Code, or a fresh chat), it
// calls GET /webhook/briefing on the Tailscale Funnel URL and receives:
//   1. Darrell's thoughts captured since the last session (from Synology
//      Chat via workflow 08, OR from /webhook/thought via workflow 26)
//      — these come FIRST, before anything else
//   2. The binding foundation principles (compressed pointers)
//   3. What's running on autopilot (workflow names, last-tick times)
//   4. What's queued (briefs in docs/99-session-notes/)
//   5. Live operational state (recent commits, latest health run)
//
// This means a future session reads Darrell's thoughts THEN operational
// state THEN principles — same order he'd brief a person.
//
// Reads:
//   /data/chatin/*.json — Synology Chat messages from workflow 08
//   /data/poetech-briefing/inbox/*.json — direct webhook thoughts from
//     workflow 26
//   /data/poetech-briefing/foundations/*.md — synced foundation docs
//   /data/poetech-briefing/session-notes/*.md — synced session notes
//   /data/finance-events/_health/*.json — workflow 20 health run snapshots

const fs = require('fs');
const path = require('path');

const CHATIN_DIR = '/data/chatin';
const BRIEFING_ROOT = '/data/poetech-briefing';
const INBOX_DIR = path.join(BRIEFING_ROOT, 'inbox');
const FOUNDATIONS_DIR = path.join(BRIEFING_ROOT, 'foundations');
const SESSION_NOTES_DIR = path.join(BRIEFING_ROOT, 'session-notes');
const STATE_DIR = path.join(BRIEFING_ROOT, 'state');
const HEALTH_DIR = '/data/finance-events/_health';

const input = $input.first().json || {};
const q = (input.query && typeof input.query === 'object') ? input.query : {};
const sinceHoursParam = parseInt(q.since_hours || '168', 10) || 168; // default last 7d
const sinceMs = Date.now() - sinceHoursParam * 3600_000;
const includeAcked = (q.include_acked || '').toLowerCase() === 'true';

function readDirSafe(dir) { try { return fs.readdirSync(dir); } catch (_) { return []; } }
function readJsonSafe(p) { try { return JSON.parse(fs.readFileSync(p, 'utf8')); } catch (_) { return null; } }
function statSafe(p) { try { return fs.statSync(p); } catch (_) { return null; } }

// 1. CHATIN (Synology Chat → @nas) thoughts.
const chatThoughts = [];
for (const f of readDirSafe(CHATIN_DIR)) {
  if (!f.endsWith('.json') || f.startsWith('_')) continue;
  const p = path.join(CHATIN_DIR, f);
  const s = statSafe(p);
  if (!s || s.mtimeMs < sinceMs) continue;
  const rec = readJsonSafe(p);
  if (!rec) continue;
  const n = rec.normalized || {};
  const text = (n.text || '').trim();
  if (!text) continue;
  // Strip the trigger word (e.g. "@nas") from the front if present
  const trigger = (n.trigger_word || '').trim();
  let cleaned = text;
  if (trigger && cleaned.startsWith(trigger)) cleaned = cleaned.slice(trigger.length).trim();
  chatThoughts.push({
    source: 'synology-chat',
    captured_at: rec.captured_at,
    sender: n.sender,
    channel: n.channel,
    text: cleaned,
    raw_text: text,
    file: f
  });
}

// 2. INBOX (direct /webhook/thought) thoughts.
const inboxThoughts = [];
for (const f of readDirSafe(INBOX_DIR)) {
  if (!f.endsWith('.json')) continue;
  const p = path.join(INBOX_DIR, f);
  const rec = readJsonSafe(p);
  if (!rec) continue;
  if (rec.ack_at && !includeAcked) continue;
  inboxThoughts.push({
    source: 'webhook-inbox',
    id: rec.id,
    captured_at: rec.captured_at,
    text: rec.text,
    tags: rec.tags || [],
    priority: rec.priority || 'normal',
    ack_at: rec.ack_at || null,
    file: f
  });
}

// Merge + sort newest first.
const allThoughts = [...chatThoughts, ...inboxThoughts].sort((a, b) => (b.captured_at || '').localeCompare(a.captured_at || ''));

// 3. Foundation + session note titles (full content not embedded — clients
//    fetch via the file paths or via the GitHub repo).
function readDirTitles(dir) {
  const out = [];
  for (const f of readDirSafe(dir)) {
    if (!f.endsWith('.md')) continue;
    const p = path.join(dir, f);
    let title = f.replace(/\.md$/, '');
    try {
      const text = fs.readFileSync(p, 'utf8');
      const m = text.match(/^#{1,2}\s+(.+)$/m);
      if (m) title = m[1].trim();
    } catch (_) {}
    out.push({ file: f, title, path: p });
  }
  return out;
}
const foundations = readDirTitles(FOUNDATIONS_DIR);
const sessionNotes = readDirTitles(SESSION_NOTES_DIR);

// 4. Live state files.
const liveState = {};
for (const f of readDirSafe(STATE_DIR)) {
  if (!f.endsWith('.json')) continue;
  const v = readJsonSafe(path.join(STATE_DIR, f));
  if (v !== null) liveState[f.replace(/\.json$/, '')] = v;
}

// 5. Latest health run.
let latestHealth = null;
{
  const names = readDirSafe(HEALTH_DIR).filter(f => f.endsWith('.json') && !f.startsWith('_')).sort();
  for (let i = names.length - 1; i >= 0; i--) {
    const r = readJsonSafe(path.join(HEALTH_DIR, names[i]));
    if (r) { latestHealth = r; break; }
  }
}

// Hard-coded fast facts always present.
const fastFacts = {
  project: 'PoeTech Family OS (SKOS / Sovereign Family Financial OS)',
  owner: 'Darrell Poe (darrellpoe06@gmail.com)',
  repo: 'https://github.com/darrellpoe06/Kingdom-PWA-Node',
  pwa_url: 'https://kingdom-pwa-node.vercel.app',
  pwa_url_custom: 'https://poetech.us',
  funnel_url: 'https://poetech.tail5a2f35.ts.net',
  binding_principles: [
    'THE-WAY — SKOS is The Way; every module operates within this frame.',
    'MIND-OF-CHRIST — NOTICE → TEST → CAPTURE → REDIRECT mental stewardship.',
    'EXCELLENCE-STANDARD — Religion AND relationship. Representatives of the King.',
    'SCRIPTURE-REFERENCE-STANDARD — ESV primary, KJV secondary, no improvised theology.',
    'ANXIETY-CLARITY-PRINCIPLE — every surface answers what/when/why/how; optimize for the scared parent.',
    'AI-FOUNDATION-INTERNAL-OPERATIONS — clicks become API calls in workflows; browsers are for humans deciding.',
    'TLC firewall — clinical content NEVER leaves the NAS.',
    'Typographic theology — capitalize Yahweh/Jesus/Holy Spirit/Father/Son and their pronouns; never capitalize lucifer/satan/devil/adversary.'
  ],
  running_on_autopilot: [
    'Workflow 08 — Synology Chat capture (#PoeTech-PWA → /data/chatin/)',
    'Workflow 15 — Bank QFX watcher (every 2 min)',
    'Workflow 16 — Reconcile engine (hourly)',
    'Workflow 18 — Imported transactions API',
    'Workflow 19 — Mark-noise API',
    'Workflow 23 — Project briefing (THIS workflow)',
    'Workflow 26 — Direct thought inbox',
    'Tailscale Funnel — public reach for n8n',
    'Vercel auto-deploy on every push to main'
  ],
  agent_posture: 'Drive don\'t delegate. Don\'t stop to ask. Once direction is set, drive until told to stop. Heartbeats yes, A/B menus no. Default to API + workflow over browser clicks per AI-FOUNDATION-INTERNAL-OPERATIONS.',
  cwd_for_code_sessions: 'C:\\Users\\dpoe\\Kingdom-PWA-Node'
};

const body = {
  served_at: new Date().toISOString(),
  // INBOX FIRST — Darrell's thoughts get read before anything else.
  inbox: {
    unread_count: allThoughts.filter(t => !t.ack_at).length,
    since_hours: sinceHoursParam,
    thoughts: allThoughts
  },
  ...fastFacts,
  foundations: foundations.length > 0 ? foundations : '(/data/poetech-briefing/foundations/ not yet synced — see binding_principles above)',
  session_notes_queued: sessionNotes,
  live_state: liveState,
  latest_health_run: latestHealth
};

return [{ json: body }];
